query GenerateTableReportWithParams($tableId: ID!, $reportType: String!, $timeRange: String) {
  generateTableReport(tableId: $tableId, reportType: $reportType, timeRange: $timeRange) {
    table {
      id
      identifier
      description
      createdAt
      lastModified
    }
    summary {
      totalNodes
      totalAttributes
      totalRelationships
      dataQualityScore
      completenessScore
    }
    trends {
      nodeGrowth {
        period
        count
        growthRate
      }
      activityPatterns {
        timeOfDay
        dayOfWeek
        activity
      }
    }
    recommendations {
      type
      priority
      description
      estimatedImpact
    }
    exportOptions {
      formats
      estimatedSize
    }
  }
}
